async function scanBundle(input, deliver) {
  let delivered = 0;
  let lineNumber = 1;
  let line = "";
  let hasCurrentLine = false;
  const decoder = new TextDecoder("utf-8");

  const processLine = async (text) => {
    if (text.endsWith("\r")) {
      text = text.slice(0, -1);
    }

    if (text.trim() === "") {
      return true;
    }

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error(`Invalid JSON on line ${lineNumber}`);
      error.code = "BAD_LINE";
      error.line = lineNumber;
      throw error;
    }

    delivered++;
    const result = await deliver(value, lineNumber);
    return result !== false;
  };

  const processText = async (text) => {
    let start = 0;

    while (true) {
      const newline = text.indexOf("\n", start);

      if (newline === -1) {
        const remainder = text.slice(start);
        if (remainder.length > 0) {
          line += remainder;
          hasCurrentLine = true;
        }
        return true;
      }

      line += text.slice(start, newline);
      const shouldContinue = await processLine(line);

      line = "";
      hasCurrentLine = false;
      lineNumber++;

      if (!shouldContinue) {
        return false;
      }

      start = newline + 1;
    }
  };

  try {
    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        break;
      }

      const text = decoder.decode(chunk, { stream: true });

      if (!(await processText(text))) {
        return delivered;
      }
    }

    const finalText = decoder.decode();

    if (!(await processText(finalText))) {
      return delivered;
    }

    if (hasCurrentLine) {
      await processLine(line);
    }

    return delivered;
  } finally {
    await input.close();
  }
}
